(function(E){ const x = E["int-m3"] = E["int-m3"] || {units:{}}; x.units["int-8"] = {"grammar":{"id":"c-int-8-g","level":"B1","course":"interview","unit":"int-8","title":"The job you imagine: would and if","titleTr":"Hayal ettiğin iş: would ve if","titleFa":"کاری که تصورش را می‌کنی: would و if","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Imagined future: would + verb","I would learn the systems first."],["if + past simple, then would + verb","If I joined your team, I would start with the reports."],["Question","What would you do in your first month?"]]},"wrong":"If I will join your team, I will learn the systems first.","right":"If I joined your team, I would learn the systems first.","blank":{"sentence":"If I got this job, I ___ the new system first.","word":"would learn","distractors":["will learn","would learned"]},"wrong2":"In my first month I would visited every branch.","right2":"In my first month I would visit every branch.","blank2":{"sentence":"If you ___ me, I would bring eight years of sales experience.","word":"hired","distractors":["hire","will hire"]},"expParts":{"rule":[{"en":"The job you imagine: would + verb.","tr":"Hayal ettiğin iş: would + fiil.","fa":"برای کاری که تصورش را می‌کنی would و فعل ساده می‌آوری.","ex":"I would learn the systems first."},{"en":"if + past simple, then would + verb.","tr":"if + past simple, sonra would + fiil.","fa":"بعد از if فعل گذشته‌ی ساده می‌آید و در بخش دوم would با فعل ساده.","ex":"If I joined your team, I would start with the reports."},{"en":"After would, the verb stays simple: no -ed, no -s.","tr":"would kelimesinden sonra fiil yalın kalır: -ed ve -s almaz.","fa":"بعد از would فعل ساده می‌ماند: بدون ‎-ed و بدون ‎-s.","ex":"I would visit every branch."}],"test":{"en":"Is it the job you imagine, not real yet? Use would + verb, and the past simple after if.","tr":"Hayal ettiğin, henüz gerçek olmayan bir iş mi? would + fiil kullan; if'ten sonra past simple.","fa":"کاری است که تصورش را می‌کنی و هنوز واقعی نیست؟ would و فعل ساده بیاور و بعد از if گذشته‌ی ساده."},"contrast":{"en":"Turkish and Persian also use a past form for an imagined future, so the idea is familiar. The trap is 'If I will...'.","tr":"Türkçedeki '-sam ... -rdım' de hayal edilen bir durum için geçmiş biçim kullanır; fikir tanıdık. Tuzak 'If I will...' demektir.","fa":"در فارسی هم «اگر ... می‌پیوستم، ... می‌کردم» برای آینده‌ی خیالی از شکل گذشته استفاده می‌کند، پس فکرش آشناست. تله «If I will...‎» است."}},"errorWatch":[{"find":["if i will","if you will hire","would learned","would visited","would trained","would worked","would made","would brought","would liked","would helped"],"fix":{"en":"Imagined job: 'If I joined..., I would + verb': 'If I joined your team, I would learn the systems first.'","tr":"Hayal edilen iş: 'If I joined..., I would + fiil': 'If I joined your team, I would learn the systems first.'","fa":"برای کار خیالی اول «If I joined...» را بگو و بعد would را با فعل ساده بیاور: «If I joined your team, I would learn the systems first.‎»"}}]},"b2":{"id":"c-int-8-b2","level":"B2","track":"B2","course":"interview","unit":"int-8","title":"By the end of year one: the future perfect","titleTr":"İlk yılın sonunda: future perfect","titleFa":"تا پایان سال اول: آینده‌ی کامل","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["will have + past participle","I will have learned every system."],["by + a time","by the end of my first year"],["Question","What will you have achieved by then?"]]},"wrong":"By the end of my first year, I will have learn every system.","right":"By the end of my first year, I will have learned every system.","blank":{"sentence":"By June I ___ all the safety courses.","word":"will have finished","distractors":["will finish until","have finished"]},"wrong2":"Until the end of the year I will have trained two new colleagues.","right2":"By the end of the year I will have trained two new colleagues.","blank2":{"sentence":"By the end of my first year, I will have ___ two new colleagues.","word":"trained","distractors":["train","training"]},"useIn":{"en":"B2: in your answer to \"Where do you see yourself...?\", use will have + past participle with by.","tr":"B2: \"Where do you see yourself...?\" sorusuna cevabında by ile will have + üçüncü hâl kullan.","fa":"در مسیر B2: در جوابت به «Where do you see yourself...?» از will have و اسم مفعول همراه با by استفاده کن."},"exitItem":{"from":"int-8","kind":"blank","prompt":"By the end of March, she ___ the first-aid course.","options":["will have completed","will complete until","has completed"],"correct":0},"expParts":{"rule":[{"en":"Finished by a future time: will have + past participle.","tr":"Gelecekteki bir zamana kadar bitmiş: will have + üçüncü hâl.","fa":"برای کاری که تا زمانی در آینده تمام شده است، will have و اسم مفعول می‌آوری.","ex":"I will have learned every system."},{"en":"Use by + a time, not until.","tr":"until değil, by + zaman kullan.","fa":"زمان را با by بیاور، نه با until.","ex":"by the end of my first year"},{"en":"Keep it real and specific.","tr":"Gerçekçi ve somut tut.","fa":"حرفت را واقعی و مشخص نگه دار.","ex":"I will have trained two new colleagues."}],"test":{"en":"Can you add 'by then'? Use will have + past participle.","tr":"'by then' ekleyebiliyor musun? will have + üçüncü hâl kullan.","fa":"می‌توانی «by then» را به جمله اضافه کنی؟ پس will have و اسم مفعول بیاور."},"contrast":{"en":"Turkish '-e kadar' and Persian 'تا' cover both by and until, so 'until the end of the year' slips in. With the future perfect, English uses by.","tr":"Türkçedeki '-e kadar' hem by hem until anlamına gelir; bu yüzden 'until the end of the year' kaçar. Future perfect ile İngilizce by kullanır.","fa":"«تا» در فارسی هم by است و هم until؛ برای همین «until the end of the year» از دهان می‌پرد. با آینده‌ی کامل، انگلیسی by می‌خواهد."}},"errorWatch":[{"find":["will have learn","will have train","will have finish","will have complete","will have achieve"],"fix":{"en":"Use will have + past participle: 'I will have learned every system.'","tr":"will have + üçüncü hâl kullan: 'I will have learned every system.'","fa":"بعد از will have اسم مفعول بیاور: «I will have learned every system.‎»"}},{"find":["until the end of the year i will have","until the end of my first year, i will have","until june i will have","until then i will have"],"fix":{"en":"With will have + past participle, use by: 'By the end of the year I will have...'","tr":"will have + üçüncü hâl ile by kullan: 'By the end of the year I will have...'","fa":"وقتی will have و اسم مفعول می‌آوری، از by استفاده کن: «By the end of the year I will have...‎»"}}]},"vocab":{"id":"c-int-8-v","level":"B1","category":"vocab","course":"interview","unit":"int-8","goals":["career"],"title":{"en":"Hard Questions","tr":"Zor Sorular","fa":"سؤال‌های سخت"},"cards":[{"word":"overview","sentence":"She started with a short overview of the role.","meaning":{"en":"A short description of the main points.","tr":"genel bakış.","fa":"نمای کلی"}},{"word":"panel","sentence":"There will be a panel of two: an HR specialist and a manager.","meaning":{"en":"A group of people who interview you together.","tr":"mülakat heyeti.","fa":"هیئت مصاحبه"}},{"word":"walk me through","sentence":"Can you walk me through one specific project?","meaning":{"en":"Explain something step by step.","tr":"adım adım anlat.","fa":"قدم‌به‌قدم توضیح بده"}},{"word":"contribute","sentence":"I could contribute my knowledge of export rules.","meaning":{"en":"To give your skills or help to a group.","tr":"katkıda bulunmak.","fa":"سهم داشتن؛ کمک کردن"}},{"word":"hire","sentence":"Why should we hire you?","meaning":{"en":"To give someone a job.","tr":"işe almak.","fa":"استخدام کردن"}},{"word":"experienced","sentence":"I would ask the experienced staff for advice.","meaning":{"en":"Having done a job for a long time.","tr":"deneyimli.","fa":"باتجربه"}},{"word":"achieve","sentence":"What would you like to achieve in your first year?","meaning":{"en":"To reach a goal by working for it.","tr":"başarmak, elde etmek.","fa":"به دست آوردن؛ رسیدن به هدف"}},{"word":"take a moment","sentence":"Feel free to take a moment before you answer.","meaning":{"en":"To stop and think for a few seconds.","tr":"biraz düşünmek için durmak.","fa":"چند لحظه فکر کردن"}},{"word":"gap","sentence":"There is a gap of ten months in my CV.","meaning":{"en":"A time in your working life with no job.","tr":"iş hayatında boşluk","fa":"وقفه در سابقه‌ی کاری"}},{"word":"let go","sentence":"I was let go when the company closed our branch.","meaning":{"en":"Told by your employer that you must leave your job.","tr":"işten çıkarılmak","fa":"تعدیل شدن از کار"}}]},"judge":{"id":"c-int-8-j","course":"interview","unit":"int-8","type":"judge","title":{"en":"Answering hard questions","tr":"Zor soruları cevaplamak","fa":"جواب دادن به سؤال‌های سخت"},"prompt":"Five answers to hard questions. Each one starts with the question.","parts":["Honest","Short, no blame","Back to this job"],"instruction":{"en":"Tap what each answer does. The strongest answer does all three.","tr":"Her cevabın ne yaptığına dokun. En güçlü cevap üçünü de yapar.","fa":"روی کاری که هر جواب می‌کند بزن. قوی‌ترین جواب هر سه را انجام می‌دهد."},"items":[{"by":"Sales assistant","answer":"\"Why did you leave your last job?\" My boss was terrible. Nobody could work with him, and the company treated all of us badly.","present":["Honest"],"fix":{"en":"Maybe true, but they will imagine you talking like this about them. Say what you want: \"I wanted a team where I could grow, and this role offers that.\"","tr":"Belki doğru, ama senin onlar hakkında da böyle konuşacağını düşünürler. Ne istediğini söyle: \"I wanted a team where I could grow, and this role offers that.\"","fa":"شاید درست باشد، ولی فکر می‌کنند درباره‌ی آن‌ها هم همین‌طور حرف خواهی زد. بگو چه می‌خواهی: «I wanted a team where I could grow, and this role offers that.»"}},{"by":"Graduate","answer":"\"You don't have experience in this field, do you?\" No, I don't. Sorry.","present":["Honest","Short, no blame"],"fix":{"en":"Honest, but it stops at the problem. Don't apologise. Go back to the job: \"Not yet, but in my final project I built a customer database like yours.\"","tr":"Dürüst, ama sorunda kalıyor. Özür dileme. Konuyu işe getir: \"Not yet, but in my final project I built a customer database like yours.\"","fa":"صادقانه است، ولی روی مشکل می‌ماند. عذرخواهی نکن. برگرد سراغ همین شغل: «Not yet, but in my final project I built a customer database like yours.»"}},{"by":"AI tool","answer":"\"Why is there a gap in your CV?\" I took that time for a meaningful journey of personal and professional growth, which has made me a more resilient professional.","present":[],"fix":{"en":"No fact, so the next question will be \"What did you actually do?\" Say it plainly: \"I cared for my father for a year. I also finished an Excel course.\"","tr":"Gerçek yok, o yüzden sıradaki soru \"What did you actually do?\" olur. Açıkça söyle: \"I cared for my father for a year. I also finished an Excel course.\"","fa":"واقعیتی در آن نیست، پس سؤال بعدی «What did you actually do?» است. ساده بگو: «I cared for my father for a year. I also finished an Excel course.»"}},{"by":"Accountant","answer":"\"What would you do if a client was angry about a late invoice?\" Well, it depends. Every client is different. I don't know, maybe I would ask my manager.","present":["Honest"],"fix":{"en":"Too vague. Say your first step and the reason: \"First I would listen and check the invoice, so I can tell the client when they will get it.\"","tr":"Fazla belirsiz. İlk adımını ve nedenini söyle: \"First I would listen and check the invoice, so I can tell the client when they will get it.\"","fa":"بیش از حد مبهم است. قدم اول و دلیلش را بگو: «First I would listen and check the invoice, so I can tell the client when they will get it.»"}},{"by":"Good model","answer":"\"Why is there a gap in your CV?\" I was let go when our branch closed in 2024. I spent six months caring for my father and finished a course in Excel. Now I am ready to work full-time, and your team uses the reports I learned to build.","present":["Honest","Short, no blame","Back to this job"],"fix":null}]},"speaking":{"rounds":[420,60,45],"id":"int-8","course":"interview","unit":"int-8","topic":{"en":"The full practice interview","tr":"Baştan sona deneme mülakatı","fa":"مصاحبه‌ی تمرینی کامل"},"warmup":{"en":"Choose one real job ad. Put your phone on the desk and press record. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries).","tr":"Gerçek bir iş ilanı seç. Telefonunu masaya koy ve kaydı başlat. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor).","fa":"یک آگهی شغلی واقعی انتخاب کن. گوشی‌ات را روی میز بگذار و دکمه‌ی ضبط را بزن. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد)."},"questions":[{"en":"So, tell me about yourself.","tr":"So, tell me about yourself.","fa":"«So, tell me about yourself.»"},{"en":"Why do you want to work for us?","tr":"Why do you want to work for us?","fa":"«Why do you want to work for us?»"},{"en":"Tell me about a time when you had a problem at work. What exactly did you do?","tr":"Tell me about a time when you had a problem at work. What exactly did you do?","fa":"«Tell me about a time when you had a problem at work. What exactly did you do?»"},{"en":"Why do you want to leave your current job?","tr":"Why do you want to leave your current job?","fa":"«Why do you want to leave your current job?»"},{"en":"If you joined us, what would you do in your first month?","tr":"If you joined us, what would you do in your first month?","fa":"«If you joined us, what would you do in your first month?»"},{"en":"Why should we hire you?","tr":"Why should we hire you?","fa":"«Why should we hire you?»"},{"en":"Do you have any questions for us?","tr":"Do you have any questions for us?","fa":"«Do you have any questions for us?»"}],"followups":[{"en":"Round 1: answer all seven once, in order, without stopping. Rounds 2 and 3: say your two weakest answers again, in 60 and then 45 seconds.","tr":"1. tur: yedi soruyu sırayla, durmadan birer kez cevapla. 2. ve 3. tur: en zayıf iki cevabını önce 60, sonra 45 saniyede yeniden söyle.","fa":"دور اول: به هر هفت سؤال به ترتیب و بدون توقف یک بار جواب بده. دور دوم و سوم: دو جواب ضعیف‌ترت را دوباره بگو، اول در ۶۰ و بعد در ۴۵ ثانیه."}],"expressions":[{"phrase":"That's a good question. Let me think for a moment.","meaning":{"en":"Gives you time, and sounds calm.","tr":"Sana zaman kazandırır ve sakin duyulur.","fa":"به تو وقت می‌دهد و آرام نشانت می‌دهد."}},{"phrase":"Do you mean...?","meaning":{"en":"Checks a question you are not sure about.","tr":"Emin olmadığın bir soruyu netleştirir.","fa":"سؤالی را که مطمئن نیستی روشن می‌کند."}},{"phrase":"If I joined..., I would...","meaning":{"en":"Talks about the job you imagine.","tr":"Hayal ettiğin işten bahseder.","fa":"از کاری که تصور می‌کنی حرف می‌زند."}}],"selfCheck":[{"en":"I answered all seven questions without stopping the recording.","tr":"Kaydı durdurmadan yedi sorunun hepsini cevapladım.","fa":"بدون قطع کردن ضبط، به هر هفت سؤال جواب دادم."},{"en":"My story had \"I\" in it, and a result.","tr":"Hikâyemde \"I\" ve bir sonuç vardı.","fa":"در ماجرایم «I» و یک نتیجه بود."},{"en":"I said nothing bad about an old manager or company.","tr":"Eski bir yönetici ya da şirket hakkında kötü bir şey söylemedim.","fa":"درباره‌ی مدیر یا شرکت قبلی هیچ حرف بدی نزدم."},{"en":"When I needed time, I used a phrase instead of silence.","tr":"Zamana ihtiyacım olunca sessiz kalmak yerine bir ifade kullandım.","fa":"وقتی زمان لازم داشتم، به‌جای سکوت از یک عبارت استفاده کردم."}],"model":"That's a good question. Let me think for a moment. You need someone who can calm angry customers and write clear reports. I have done both for five years. If I joined your team, I would first listen to twenty support calls, and then I would learn your system. You would have someone useful from the first month."},"writing":{"id":"c-int-8-w","course":"interview","unit":"int-8","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your hard-question sheet","tr":"Zor soru sayfan","fa":"برگه‌ی سؤال‌های سخت تو"},"portfolio":"int-final-5","prompt":{"en":"Write short, honest answers to the three hard questions that worry you most (80-120 words in total). Use: (1) why you want to leave, or a gap, or missing experience; (2) \"What would you do if...?\" with a problem from your work; (3) \"Why should we hire you?\" No problem of your own? Use this one: a flight is cancelled, and the customer is shouting.","tr":"Seni en çok zorlayan üç soruya kısa ve dürüst cevaplar yaz (toplam 80-120 kelime). Şunları kullan: (1) neden ayrılmak istediğin, bir boşluk ya da eksik deneyim; (2) işinden bir sorunla \"What would you do if...?\"; (3) \"Why should we hire you?\" Kendi işinden bir sorun yoksa şunu kullan: uçuş iptal edildi ve müşteri bağırıyor.","fa":"به سه سؤال سختی که بیشتر از همه نگرانت می‌کند جواب کوتاه و صادقانه بده (در مجموع ۸۰ تا ۱۲۰ کلمه). این‌ها را بیاور: (۱) چرا می‌خواهی بروی، یا وقفه‌ی کاری، یا تجربه‌ی کم؛ (۲) «What would you do if...?» با مشکلی از کار خودت؛ (۳) «Why should we hire you?» مشکلی از کار خودت نداری؟ از این استفاده کن: پرواز لغو شده و مشتری داد می‌زند."},"model":"Why do you want to leave? I have learned a lot in four years, and I am ready for a bigger team. I enjoy my work, but there is no room to grow.\n\nWhat would you do if a customer got angry? First I would listen and write down the problem. Then I would say what I can do today. If I could not solve it, I would ask my manager and call back the same day.\n\nWhy should we hire you? You need clear reports and calm service. I have done both for five years, and I learn new systems fast.","frame":"Why do you want to leave? I have ___, and I am ready for ___.\n\nWhat would you do if ___? First I would ___. Then I would ___. If I could not ___, I would ___.\n\nWhy should we hire you? You need ___. I have ___.","words":[{"word":"would listen"},{"word":"If I could not"},{"word":"hire"}],"minWords":80,"minSentences":6,"rubric":["Task done: three hard questions, each with a real answer","Organised: honest fact first, then what you did or would do, then the job","Language: would + verb and if + past simple for what you would do","Tone: calm and honest; no blame, no apology, no big empty words"],"rubricI18n":{"tr":["Görev: üç zor soru, her birine gerçek bir cevap","Düzen: önce dürüst gerçek, sonra ne yaptığın ya da yapacağın, sonra iş","Dil: yapacakların için would + fiil ve if + past simple","Üslup: sakin ve dürüst; suçlama yok, özür yok, içi boş büyük laf yok"],"fa":["کامل بودن کار: سه سؤال سخت، هر کدام با یک جواب واقعی","نظم: اول واقعیت صادقانه، بعد کاری که کردی یا می‌کنی، بعد خود این کار","زبان: would با فعل ساده و if با گذشته‌ی ساده برای کاری که تصور می‌کنی","لحن: آرام و صادق؛ بدون مقصر دانستن، بدون عذرخواهی، بدون کلمه‌های بزرگ توخالی"]}},"exit":{"id":"c-int-8-x","course":"interview","unit":"int-8","type":"exit","items":[{"from":"int-8","kind":"blank","prompt":"If I worked here, I ___ to improve the night schedule.","options":["would try","will try","would tried"],"correct":0,"point":2},{"from":"int-8","kind":"blank","prompt":"If the company ___ me, I would move to Ankara with my family.","options":["will choose","chose","would choose"],"correct":1,"point":2},{"from":"int-8","kind":"mcq","prompt":"The interviewer asks a question you did not expect. What is best?","options":["Stay silent and look at the table until an idea comes","Say \"That's a good question. Let me think for a moment.\"","Say \"I don't know\" and wait for the next question to come"],"correct":1,"point":1},{"from":"int-7","kind":"mcq","prompt":"Which question should you keep for the offer stage?","options":["How much holiday will I get each year?","What does a typical first month look like?","What are the next steps after today?"],"correct":0},{"from":"int-5","kind":"mcq","prompt":"Which sentence shows your own action in a STAR story?","options":["We were a great team, and we all worked hard.","I called the client and offered a new time.","Our team solved it together in the end."],"correct":1},{"from":"int-1","kind":"blank","prompt":"She ___ in recruitment since she moved to Dubai.","options":["works","worked","has worked"],"correct":2}]},"explain":{"id":"c-int-8-e","course":"interview","unit":"int-8","type":"explain","level":"B1","title":{"en":"Hard questions and the full run","tr":"Zor sorular ve tam deneme","fa":"سؤال‌های سخت و مصاحبه‌ی کامل"},"objective":{"en":"In this lesson you will learn to answer hard questions honestly and get through a full practice interview.","tr":"Bu derste zor soruları dürüstçe cevaplamayı ve baştan sona bir deneme mülakatını yürütmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری به سؤال‌های سخت صادقانه جواب بدهی و یک مصاحبه‌ی تمرینی کامل را پیش ببری."},"hook":{"en":"Hard questions test how you think under pressure. You don't need a perfect answer. Give a short, honest one, blame nobody, and bring the talk back to this job.","tr":"Zor sorular baskı altında nasıl düşündüğünü ölçer. Kusursuz bir cevap gerekmez. Kısa ve dürüst cevap ver, kimseyi suçlama ve konuyu bu işe getir.","fa":"سؤال‌های سخت می‌سنجند زیر فشار چطور فکر می‌کنی. جواب بی‌نقص لازم نیست. کوتاه و صادقانه جواب بده، کسی را مقصر ندان و حرف را به همین شغل برگردان."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Four kinds of hard moment","tr":"Dört tür zor an","fa":"چهار نوع لحظه‌ی سخت"},"steps":[{"en":"If you are lost, check the question, or ask for a moment. A short silence looks calm.","tr":"Soruyu anlamadıysan netleştir ya da bir an iste. Kısa bir sessizlik sakin görünür.","fa":"اگر سؤال را متوجه نشدی، دوباره بپرس یا لحظه‌ای وقت بخواه. سکوت کوتاه نشانه‌ی آرامش است.","ex":"Do you mean my last job or this one?"},{"en":"For a gap, leaving or little experience, say one honest sentence. Long reasons sound like excuses.","tr":"Boşluk, ayrılma ya da az deneyim için dürüst bir cümle söyle. Uzun nedenler bahane gibi duyulur.","fa":"برای وقفه، ترک شغل یا تجربه‌ی کم یک جمله‌ی صادقانه بگو. دلیل‌های طولانی بهانه به نظر می‌رسند.","ex":"I was let go (I lost my job) when our branch closed. Since then I..."},{"en":"\"What would you do if...?\": say your first step, why, and who you would tell.","tr":"\"What would you do if...?\": ilk adımını, nedenini ve kime söyleyeceğini anlat.","fa":"اگر پرسیدند «What would you do if...?»، بگو اولین قدمت چیست، چرا و به چه کسی خبر می‌دهی.","ex":"First I would listen. Then I would tell my manager."},{"en":"\"Why should we hire you?\": join what they need to your proof. That makes it about them.","tr":"\"Why should we hire you?\": ihtiyaçlarını kanıtınla birleştir. Böylece cevap onlarla ilgili olur.","fa":"در جواب «Why should we hire you?» چیزی را که لازم دارند به شاهد خودت وصل کن، چون این‌طوری جواب درباره‌ی آن‌هاست.","ex":"You need clear reports. I have written them for five years."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"The job you imagine: would and if","tr":"Hayal ettiğin iş: would ve if","fa":"کاری که تصورش را می‌کنی: would و if"},"steps":[{"en":"The job you imagine: would + verb.","tr":"Hayal ettiğin iş: would + fiil.","fa":"برای کاری که تصورش را می‌کنی would و فعل ساده می‌آوری.","ex":"I would learn the systems first."},{"en":"if + past simple, then would + verb.","tr":"if + past simple, sonra would + fiil.","fa":"بعد از if فعل گذشته‌ی ساده می‌آید و در بخش دوم would با فعل ساده.","ex":"If I joined your team, I would start with the reports."},{"en":"After would, the verb stays simple: no -ed, no -s.","tr":"would kelimesinden sonra fiil yalın kalır: -ed ve -s almaz.","fa":"بعد از would فعل ساده می‌ماند: بدون ‎-ed و بدون ‎-s.","ex":"I would visit every branch."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Imagined future: would + verb","I would learn the systems first."],["if + past simple, then would + verb","If I joined your team, I would start with the reports."],["Question","What would you do in your first month?"]]},"tip":{"en":"Turkish and Persian also use a past form for an imagined future, so the idea is familiar. The trap is 'If I will...'.","tr":"Türkçedeki '-sam ... -rdım' de hayal edilen bir durum için geçmiş biçim kullanır; fikir tanıdık. Tuzak 'If I will...' demektir.","fa":"در فارسی هم «اگر ... می‌پیوستم، ... می‌کردم» برای آینده‌ی خیالی از شکل گذشته استفاده می‌کند، پس فکرش آشناست. تله «If I will...‎» است."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Personal questions","tr":"Kişisel sorular","fa":"سؤال‌های شخصی"},"body":{"en":"Marriage, children or religion? In many countries employers should not decide on these, but the rules differ, so check yours. You can answer briefly and go back to the job: \"That won't affect my work. I can work the hours in the ad.\"","tr":"Evlilik, çocuk ya da din? Birçok ülkede işverenler buna göre karar vermemeli, ama kurallar değişir; kendi ülkene bak. Kısa cevap verip konuyu işe getirebilirsin: \"That won't affect my work. I can work the hours in the ad.\"","fa":"ازدواج، بچه یا دین؟ در خیلی از کشورها کارفرما نباید بر این اساس تصمیم بگیرد، ولی قانون‌ها فرق دارند؛ قانون کشور خودت را بررسی کن. می‌توانی کوتاه جواب بدهی و برگردی سراغ همین شغل: «That won't affect my work. I can work the hours in the ad.»"},"phrases":[{"phrase":"That's a good question. Let me think for a moment.","meaning":{"en":"Gives you time, and sounds calm.","tr":"Sana zaman kazandırır ve sakin duyulur.","fa":"به تو وقت می‌دهد و آرام نشانت می‌دهد."}},{"phrase":"Do you mean...?","meaning":{"en":"Checks a question you are not sure about.","tr":"Emin olmadığın bir soruyu netleştirir.","fa":"سؤالی را که مطمئن نیستی روشن می‌کند."}},{"phrase":"If I joined..., I would...","meaning":{"en":"Talks about the job you imagine.","tr":"Hayal ettiğin işten bahseder.","fa":"از کاری که تصور می‌کنی حرف می‌زند."}},{"phrase":"gap","meaning":{"en":"A time in your working life with no job.","tr":"iş hayatında boşluk","fa":"وقفه در سابقه‌ی کاری"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Answer without blame","tr":"Suçlamadan cevapla","fa":"بدون مقصر دانستن جواب بده"},"item":"Weak: My boss was terrible, so I left. The company also treated everyone very badly. Your facts: you wanted more responsibility; this role offers it; you have led a small team.","answer":"I left because I wanted more responsibility. This role offers that, and I have already led a small team.","walk":[{"en":"Drop the boss and the company. Don't lie, but blame makes them wonder what you would say about them.","tr":"Patronu ve şirketi çıkar. Yalan söyleme, ama suçlamak onlar hakkında ne söyleyeceğini düşündürür.","fa":"از رئیس و شرکت قبلی حرف نزن. دروغ نگو، ولی اگر کسی را مقصر بدانی، از خودشان می‌پرسند درباره‌ی ما چه خواهد گفت."},{"en":"Say what you wanted.","tr":"Ne istediğini söyle.","fa":"بگو چه می‌خواستی."},{"en":"Go back to this job, with one fact.","tr":"Bir gerçekle konuyu bu işe getir.","fa":"با یک واقعیت برگرد سراغ همین شغل."}]},"quick":{"prompt":"If I joined your team, I ___ the reports first.","options":["would learn","will learn","learned"],"correct":0,"why":{"en":"would learn: the job is still imagined, so use if + past simple, then would + verb.","tr":"would learn: iş henüz hayal aşamasında, o yüzden if + past simple, sonra would + fiil.","fa":"جواب would learn است، چون این کار هنوز در حد تصور است: بعد از if گذشته‌ی ساده می‌آید و بعد would با فعل ساده."}},"remember":{"en":"Honest, short, back to the job. You can now answer hard questions without blame or long excuses and keep going through a full interview. Next, you do a full practice interview and write your hardest answers.","tr":"Dürüst ol, kısa tut, konuyu işe getir. Artık zor soruları suçlamadan ve uzun bahaneler olmadan cevaplayabilir, mülakatı sonuna kadar sürdürebilirsin. Sırada baştan sona bir deneme mülakatı ve en zor cevaplarını yazmak var.","fa":"صادق باش، کوتاه جواب بده و حرف را به همین شغل برگردان. حالا می‌توانی بدون مقصر دانستن و بهانه‌ی طولانی به سؤال‌های سخت جواب بدهی و مصاحبه را تا آخر پیش ببری. در ادامه یک مصاحبه‌ی تمرینی کامل انجام می‌دهی و سخت‌ترین جواب‌هایت را می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"By the end of year one: the future perfect","tr":"İlk yılın sonunda: future perfect","fa":"تا پایان سال اول: آینده‌ی کامل"},"steps":[{"en":"Finished by a future time: will have + past participle.","tr":"Gelecekteki bir zamana kadar bitmiş: will have + üçüncü hâl.","fa":"برای کاری که تا زمانی در آینده تمام شده است، will have و اسم مفعول می‌آوری.","ex":"I will have learned every system."},{"en":"Use by + a time, not until.","tr":"until değil, by + zaman kullan.","fa":"زمان را با by بیاور، نه با until.","ex":"by the end of my first year"},{"en":"Keep it real and specific.","tr":"Gerçekçi ve somut tut.","fa":"حرفت را واقعی و مشخص نگه دار.","ex":"I will have trained two new colleagues."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["will have + past participle","I will have learned every system."],["by + a time","by the end of my first year"],["Question","What will you have achieved by then?"]]},"body":{"en":"B2: in your answer to \"Where do you see yourself...?\", use will have + past participle with by.","tr":"B2: \"Where do you see yourself...?\" sorusuna cevabında by ile will have + üçüncü hâl kullan.","fa":"در مسیر B2: در جوابت به «Where do you see yourself...?» از will have و اسم مفعول همراه با by استفاده کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
